    inline Appearance const* Find(uint32 form, bool shiny)
    {
        uint64 const key = uint64(form) * 2 + uint64(shiny);
        auto it = std::lower_bound(std::begin(Appearances), std::end(Appearances), key,
            [](Appearance const& row, uint64 value) { return uint64(row.form) * 2 + uint64(row.shiny) < value; });
        return it != std::end(Appearances) && it->form == form && it->shiny == shiny ? it : nullptr;
    }

    inline bool PreferredShiny(uint32 form, bool desired)
    {
        return Find(form, desired) ? desired : !desired;
    }

    inline uint32 Display(uint32 form, bool shiny)
    {
        auto row = Find(form, shiny);
        return row ? row->display : 0;
    }

    inline bool Parse(uint32 display, uint32& form, bool& shiny)
    {
        for (auto const& row : Appearances)
            if (row.display == display)
            {
                form = row.form;
                shiny = row.shiny;
                return true;
            }
        return false;
    }
